(7588538, 1221644, 173844, '<td valign="top">After some head swiveling it appears that this image would be cool in any orientation.  Taut and exciting.  All decked out in red and black, this is GQ material.</td>', 'After some head swiveling it appears that this image would be cool in any orientation.  Taut and exciting.  All decked out in red and black, this is GQ material.', '2018-08-02 14:11:19.000000', NULL, 1),
(7588540, 1221518, 173844, '<td valign="top">Not only are the butterflies beautifully photographed, the story, not being conversant in butterfly etiquette, is also intriguing.  The come on or the brush off?  Don''t know, don''t have any idea.  Love those curled up tongues.</td>', 'Not only are the butterflies beautifully photographed, the story, not being conversant in butterfly etiquette, is also intriguing.  The come on or the brush off?  Don''t know, don''t have any idea.  Love those curled up tongues.', '2018-08-02 14:16:30.000000', NULL, 1),
(7588542, 1220756, 173844, '<td valign="top">That''s just so startling!  The focus amidst the action makes this capture special.  Imagine how the mouse feels.</td>', 'That''s just so startling!  The focus amidst the action makes this capture special.  Imagine how the mouse feels.', '2018-08-02 14:20:04.000000', NULL, 1),
(7588543, 1221605, 173844, '<td valign="top">This is pretty, Norman Rockwell warm and succulent.  How many stacks did you have to eat before you got the perfect shot?</td>', 'This is pretty, Norman Rockwell warm and succulent.  How many stacks did you have to eat before you got the perfect shot?', '2018-08-02 14:22:39.000000', NULL, 1),
(7588548, 1221618, 173844, '<td valign="top">The mixing at the top, or embrace, if you will, suggests that this isn''t the first go.  Skipping the racy part, I like the rakish tilt of the blue glass and the perspiration on the outside of them both, which adds interest to the liquids.</td>', 'The mixing at the top, or embrace, if you will, suggests that this isn''t the first go.  Skipping the racy part, I like the rakish tilt of the blue glass and the perspiration on the outside of them both, which adds interest to the liquids.', '2018-08-02 14:32:20.000000', NULL, 1),
(7588550, 1221113, 173844, '<td valign="top">Voila, science.  Neat demonstration.</td>', 'Voila, science.  Neat demonstration.', '2018-08-02 14:37:49.000000', NULL, 1),
(7588553, 1221113, 117534, '<td valign="top">Awesome</td>', 'Awesome', '2018-08-02 14:41:03.000000', NULL, 1),
